from __future__ import annotations

from html import escape

from fastapi import APIRouter, HTTPException, Request
from fastapi.responses import HTMLResponse

from .branding import BRAND_ART_ROUTE, ENDORSEMENT, PRODUCT_FULL_NAME, TAGLINE
from .plans import AUTOMATION, BASIC_TIMELINE

router = APIRouter(tags=["Professional Creative Editor Workspace"])


def _member(request: Request):
    member = getattr(request.state, "member", None)
    if member is None:
        raise HTTPException(401, "Membership context unavailable")
    if not member.plan.has(BASIC_TIMELINE):
        raise HTTPException(403, "Professional Video/Image editing unlocks on the Basic membership tier")
    return member


@router.get("/creative/editor-workspace", response_class=HTMLResponse, include_in_schema=False)
def professional_editor_workspace(request: Request, project: str = ""):
    member = _member(request)
    plan_name = escape(member.plan.name)
    pro_enabled = member.plan.has(AUTOMATION)
    initial_project = escape((project or "").strip()[:160], quote=True)
    html = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="robots" content="noindex,nofollow"><title>Professional Editor — __PRODUCT__</title>
<style>
:root{--bg:#04050b;--panel:#0d101bdc;--panel2:#080a12;--line:#ffffff1c;--gold:#f2c970;--violet:#a36cff;--cyan:#5fe8ff;--green:#77dda3;--red:#ff8d9d;--text:#fff;--muted:#b8bdd0}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 10% 0,#38144f,transparent 28%),radial-gradient(circle at 90% 0,#12394f,transparent 26%),#03040a;color:var(--text);font-family:Inter,system-ui,sans-serif;min-height:100vh}button,input,select{font:inherit}a{color:inherit;text-decoration:none}.top{height:66px;position:sticky;top:0;z-index:20;display:flex;align-items:center;gap:10px;padding:0 14px;border-bottom:1px solid var(--line);background:#05060bed;backdrop-filter:blur(18px)}.brand{font-weight:900;min-width:250px}.brand small{display:block;color:var(--gold);font-size:.62rem;text-transform:uppercase;letter-spacing:.08em}.grow{flex:1}.btn{border:1px solid var(--line);background:#ffffff08;color:white;padding:8px 10px;border-radius:10px;font-weight:800;cursor:pointer}.btn.primary{border:0;background:linear-gradient(110deg,#fff0ae,var(--gold),#c69cff);color:#170d20}.btn:disabled{opacity:.38;cursor:not-allowed}.field{border:1px solid var(--line);background:#070912;color:#fff;border-radius:10px;padding:9px;min-width:0}.project{width:min(280px,30vw)}.status{font-size:.72rem;color:var(--muted)}.shell{height:calc(100vh - 66px);display:grid;grid-template-columns:260px minmax(420px,1fr) 310px;grid-template-rows:minmax(300px,1fr) 270px;gap:8px;padding:8px}.panel{border:1px solid var(--line);background:linear-gradient(145deg,#101321e8,#080a12ee);border-radius:15px;min-width:0;min-height:0;overflow:hidden}.panelhead{display:flex;align-items:center;gap:8px;padding:10px 12px;border-bottom:1px solid var(--line);font-size:.76rem;font-weight:900}.muted{color:var(--muted)}.library{grid-row:1/3}.scroll{height:calc(100% - 42px);overflow:auto;padding:8px}.asset,.trackrow{border:1px solid var(--line);border-radius:11px;padding:9px;margin-bottom:6px;background:#ffffff04;cursor:pointer}.asset.active,.clip.active{border-color:#f2c97088;box-shadow:0 0 0 2px #f2c97016}.chip{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:2px 6px;font-size:.61rem;margin-top:4px;color:var(--muted)}.viewer{display:flex;flex-direction:column}.stage{flex:1;display:flex;align-items:center;justify-content:center;position:relative;overflow:hidden;background:linear-gradient(45deg,#0a0b10 25%,#0f1017 25%,#0f1017 50%,#0a0b10 50%,#0a0b10 75%,#0f1017 75%);background-size:28px 28px}.stage img,.stage video{display:block;max-width:92%;max-height:88%;object-fit:contain;box-shadow:0 20px 55px #000a}.empty{padding:22px;text-align:center;color:var(--muted);line-height:1.55}.transport{height:50px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:center;gap:8px}.inspector{grid-row:1/3}.section{padding:10px;border-bottom:1px solid var(--line)}.section h3{font-size:.75rem;margin:0 0 8px;color:var(--gold);text-transform:uppercase;letter-spacing:.08em}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:6px}.label{display:grid;gap:3px;font-size:.64rem;color:var(--muted)}.timeline{grid-column:2}.timelinebody{height:calc(100% - 42px);overflow:auto;padding:8px}.track{display:grid;grid-template-columns:120px 1fr;min-height:54px;border-bottom:1px solid #ffffff10}.trackname{padding:8px;font-size:.68rem;border-right:1px solid #ffffff10}.lane{position:relative;min-width:600px}.clip{position:absolute;top:7px;height:38px;border:1px solid #a36cff66;border-radius:8px;background:linear-gradient(100deg,#6c42a955,#2d789155);padding:6px;overflow:hidden;font-size:.63rem;cursor:pointer}.clip.image_layer{border-color:#5fe8ff66}.clip.audio_clip{border-color:#77dda366}.timelinebar{display:flex;gap:6px;margin-left:auto}.truth{color:#8ddfb2;font-size:.65rem}.danger{color:var(--red)}@media(max-width:1050px){.shell{grid-template-columns:210px 1fr;grid-template-rows:minmax(300px,1fr) 260px 380px;height:auto}.inspector{grid-column:1/3;grid-row:3}.library{grid-row:1/3}.timeline{grid-column:2}.top{flex-wrap:wrap;height:auto;padding:9px}.shell{height:auto}.brand{min-width:0}.project{width:220px}}@media(max-width:720px){.shell{display:block}.panel{margin-bottom:8px;min-height:330px}.library,.timeline,.inspector{min-height:360px}.project{width:100%}.top{position:relative}.brand{width:100%}}
</style></head><body data-pro="__PRO__" data-project="__INITIAL_PROJECT__">
<header class="top"><a class="brand" href="/dashboard">__PRODUCT__<small>__ENDORSEMENT__</small></a><input id="project" class="field project" placeholder="Project ID"><button class="btn primary" id="load">Open editor</button><button class="btn" id="sync">Sync Creative DNA</button><span id="status" class="status grow">Professional non-destructive editor · __PLAN__</span><a class="btn" href="/creative-house">Creative House</a></header>
<main class="shell">
<section class="panel library"><div class="panelhead"><span>Media & Layers</span><span class="grow"></span><button class="btn" id="addTrack">+ Track</button></div><div id="library" class="scroll"><div class="empty">Open a project to load editable sequences, tracks and media references.</div></div></section>
<section class="panel viewer"><div class="panelhead"><span id="sequenceTitle">Program Monitor</span><span class="grow"></span><span class="truth">Source media is never overwritten</span></div><div id="stage" class="stage"><div class="empty">Select an image or video item to preview its registered Creative Element source.</div></div><div class="transport"><button class="btn" id="undo">↶ Undo</button><button class="btn" id="redo">↷ Redo</button><button class="btn" id="duplicate">Duplicate</button><button class="btn" id="split">Split @ playhead</button><input id="playhead" class="field" type="number" min="0" step="0.01" value="0" style="width:90px" aria-label="Playhead seconds"></div></section>
<section class="panel timeline"><div class="panelhead"><span>Timeline / Layer Stack</span><div class="timelinebar"><button class="btn" id="ripple">Ripple delete</button><button class="btn" id="branch">A/B Branch</button></div></div><div id="timeline" class="timelinebody"><div class="empty">Timeline appears after a project is opened.</div></div></section>
<aside class="panel inspector"><div class="panelhead"><span>Inspector</span><span class="grow"></span><span id="selectionName" class="muted">Nothing selected</span></div><div class="scroll">
<div class="section"><h3>Transform</h3><div class="grid2"><label class="label">X<input class="field edit" data-group="transform" data-key="x" type="number" step="1"></label><label class="label">Y<input class="field edit" data-group="transform" data-key="y" type="number" step="1"></label><label class="label">Scale X<input class="field edit" data-group="transform" data-key="scale_x" type="number" step=".01"></label><label class="label">Scale Y<input class="field edit" data-group="transform" data-key="scale_y" type="number" step=".01"></label><label class="label">Rotation<input class="field edit" data-group="transform" data-key="rotation" type="number" step=".1"></label><label class="label">Opacity<input class="field edit" data-key="opacity" type="number" min="0" max="1" step=".01"></label></div></div>
<div class="section"><h3>Crop</h3><div class="grid2"><label class="label">Left<input class="field edit" data-group="crop" data-key="left" type="number" min="0" max=".99" step=".01"></label><label class="label">Right<input class="field edit" data-group="crop" data-key="right" type="number" min="0" max=".99" step=".01"></label><label class="label">Top<input class="field edit" data-group="crop" data-key="top" type="number" min="0" max=".99" step=".01"></label><label class="label">Bottom<input class="field edit" data-group="crop" data-key="bottom" type="number" min="0" max=".99" step=".01"></label></div></div>
<div class="section"><h3>Colour</h3><div class="grid2"><label class="label">Exposure<input class="field edit" data-group="color" data-key="exposure" type="number" step=".1"></label><label class="label">Contrast<input class="field edit" data-group="color" data-key="contrast" type="number" step=".05"></label><label class="label">Saturation<input class="field edit" data-group="color" data-key="saturation" type="number" step=".05"></label><label class="label">Brightness<input class="field edit" data-group="color" data-key="brightness" type="number" step=".05"></label></div></div>
<div class="section"><h3>Timeline</h3><div class="grid2"><label class="label">Start<input class="field edit" data-key="start" type="number" min="0" step=".01"></label><label class="label">Duration<input class="field edit" data-key="duration" type="number" min=".01" step=".01"></label><label class="label">Source in<input class="field edit" data-key="source_in" type="number" min="0" step=".01"></label><label class="label">Speed<input class="field edit" data-key="speed" type="number" min=".05" max="20" step=".05"></label></div></div>
<div class="section"><h3>Pro controls</h3><p class="muted" style="font-size:.7rem">Keyframe, mask, effects and metadata-only A/B branching are Pro capabilities. This workspace exposes branching now; detailed graph/keyframe panels are the next UI slice.</p><button class="btn" id="addMask">Add rectangle mask</button> <button class="btn" id="addEffect">Add colour effect</button></div>
<div class="section"><h3>Export truth boundary</h3><p class="muted" style="font-size:.7rem">This workspace edits the real persistent edit graph. Final compositor/export rendering is not labelled complete here. Existing Creative Element media is previewed only through the private media endpoint.</p></div>
</div></aside></main>
<script>
const $=id=>document.getElementById(id);let state=null,selected=null,selectedSequence=null;
const pro=document.body.dataset.pro==='true';$('project').value=document.body.dataset.project||'';
function project(){return $('project').value.trim()}function status(msg,bad=false){$('status').textContent=msg;$('status').className='status grow'+(bad?' danger':'')}
async function api(path,opt={}){const r=await fetch(path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});let b={};try{b=await r.json()}catch(_){}if(!r.ok)throw new Error(b.detail||`Request failed (${r.status})`);return b}
function endpoint(s=''){return `/creative/projects/${encodeURIComponent(project())}/editor${s}`}
async function openEditor(){if(!project())return status('Enter a project ID.',true);try{let b;try{b=await api(endpoint())}catch(e){if(!String(e.message).includes('not initialized'))throw e;b=await api(endpoint('/initialize'),{method:'POST',body:JSON.stringify({sync_creative_manifest:true})})}state=b.editor||b;selected=null;render();status(`Editor loaded · ${state.project_name} · source media remains non-destructive`)}catch(e){status(e.message,true)}}
async function mutate(path,body){try{const b=await api(endpoint(path),{method:'POST',body:body===undefined?'{}':JSON.stringify(body)});state=b.editor||state;render();return b}catch(e){status(e.message,true);throw e}}
async function patchItem(changes){if(!selected)return;try{const b=await api(endpoint(`/items/${encodeURIComponent(selected.id)}`),{method:'PATCH',body:JSON.stringify({changes})});state=b.editor;selected=b.item;render(false);fillInspector();status(`Saved ${selected.name}`)}catch(e){status(e.message,true)}}
function branch(){return state?.branch||{sequences:[],tracks:[],items:[]}}function item(id){return branch().items.find(x=>x.id===id)}function track(id){return branch().tracks.find(x=>x.id===id)}
function choose(id){selected=item(id)||null;fillInspector();renderPreview();document.querySelectorAll('.clip,.asset').forEach(x=>x.classList.toggle('active',x.dataset.id===id))}
function fillInspector(){const name=$('selectionName');name.textContent=selected?selected.name:'Nothing selected';document.querySelectorAll('.edit').forEach(input=>{input.disabled=!selected;if(!selected){input.value='';return}const group=input.dataset.group,key=input.dataset.key;const value=group?(selected[group]||{})[key]:selected[key];input.value=value??''});$('duplicate').disabled=!selected;$('split').disabled=!selected||!['video_clip','audio_clip'].includes(selected.kind);$('ripple').disabled=!selected;$('addMask').disabled=!selected||!pro;$('addEffect').disabled=!selected||!pro;$('branch').disabled=!pro}
function renderPreview(){const stage=$('stage');if(!selected){stage.innerHTML='<div class="empty">Select an image or video item to preview its registered Creative Element source.</div>';return}if(!selected.source_element_id){stage.innerHTML='<div class="empty">This item has no registered Creative Element media endpoint. Its edit metadata remains fully available.</div>';return}const src=`/creative/projects/${encodeURIComponent(project())}/elements/${encodeURIComponent(selected.source_element_id)}/media`;if(selected.kind==='image_layer')stage.innerHTML=`<img src="${src}" alt="Selected image layer">`;else if(selected.kind==='video_clip')stage.innerHTML=`<video src="${src}" controls playsinline preload="metadata"></video>`;else stage.innerHTML='<div class="empty">Audio/text items are represented on the timeline; use the Music Studio for waveform/audio monitoring.</div>'}
function render(keepSelection=true){if(!state)return;const b=branch();if(!selectedSequence||!b.sequences.some(x=>x.id===selectedSequence.id))selectedSequence=b.sequences[0]||null;$('sequenceTitle').textContent=selectedSequence?`${selectedSequence.name} · ${selectedSequence.width}×${selectedSequence.height}`:'Program Monitor';const lib=[];for(const seq of b.sequences){lib.push(`<div class="asset"><b>${esc(seq.name)}</b><div><span class="chip">${esc(seq.kind)}</span><span class="chip">${seq.width}×${seq.height}</span></div></div>`);for(const tid of seq.track_ids){const t=track(tid);if(!t)continue;lib.push(`<div class="asset"><b>${esc(t.name)}</b><div><span class="chip">${esc(t.kind)}</span>${t.locked?'<span class="chip">LOCKED</span>':''}</div></div>`);for(const iid of t.item_ids){const it=item(iid);if(it)lib.push(`<div class="asset" data-id="${esc(it.id)}" onclick="choose('${js(it.id)}')"><b>${esc(it.name)}</b><div><span class="chip">${esc(it.kind)}</span><span class="chip">${it.start.toFixed(2)}s</span></div></div>`)}}} $('library').innerHTML=lib.join('')||'<div class="empty">No sequences yet. Sync Creative DNA or add a sequence through the API.</div>';
let html='';if(selectedSequence){const px=18;for(const tid of selectedSequence.track_ids){const t=track(tid);if(!t)continue;html+=`<div class="track"><div class="trackname"><b>${esc(t.name)}</b><br><span class="muted">${esc(t.kind)}</span></div><div class="lane">`;for(const iid of t.item_ids){const it=item(iid);if(!it)continue;const left=Math.max(0,it.start*px),width=Math.max(36,it.duration*px);html+=`<div class="clip ${esc(it.kind)}" data-id="${esc(it.id)}" onclick="choose('${js(it.id)}')" style="left:${left}px;width:${width}px">${esc(it.name)} · ${it.duration.toFixed(2)}s</div>`}html+='</div></div>'}}$('timeline').innerHTML=html||'<div class="empty">No tracks in this sequence.</div>';if(keepSelection&&selected){const refreshed=item(selected.id);selected=refreshed||null}fillInspector();renderPreview()}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function js(v){return String(v).replace(/\\/g,'\\\\').replace(/'/g,"\\'")}
$('load').onclick=openEditor;$('sync').onclick=async()=>{if(!project())return status('Enter a project ID.',true);const b=await mutate('/sync-manifest');state=b.editor;render();status(`Creative DNA sync complete · ${b.sync?.imported||0} new media element(s)`) };
$('undo').onclick=async()=>mutate('/undo');$('redo').onclick=async()=>mutate('/redo');$('duplicate').onclick=async()=>{if(selected)await mutate(`/items/${encodeURIComponent(selected.id)}/duplicate`,{})};$('split').onclick=async()=>{if(selected)await mutate(`/items/${encodeURIComponent(selected.id)}/split`,{time:Number($('playhead').value)})};$('ripple').onclick=async()=>{if(selected&&confirm(`Ripple delete ${selected.name}?`)){await mutate(`/items/${encodeURIComponent(selected.id)}/ripple-delete`);selected=null}};
$('branch').onclick=async()=>{if(!pro)return status('A/B editor branching requires Pro.',true);const name=prompt('Branch name','Alternate cut');if(name){await mutate('/branches',{name});selected=null}};$('addMask').onclick=async()=>{if(selected&&pro)await mutate(`/items/${encodeURIComponent(selected.id)}/masks`,{name:'Rectangle Mask',shape:'rectangle',points:[[.1,.1],[.9,.9]]})};$('addEffect').onclick=async()=>{if(selected&&pro)await mutate(`/item/${encodeURIComponent(selected.id)}/effects`,{type:'color_adjust',parameters:{}})};
$('addTrack').onclick=()=>status('Track creation is available through the editor API; a sequence/track creation dialog is the next workspace UI slice.');document.querySelectorAll('.edit').forEach(input=>input.addEventListener('change',()=>{if(!selected)return;const value=Number(input.value);if(!Number.isFinite(value))return;const group=input.dataset.group,key=input.dataset.key;patchItem(group?{[group]:{[key]:value}}:{[key]:value})}));
if(project())openEditor();else fillInspector();
</script></body></html>'''
    return HTMLResponse(
        html.replace("__PRODUCT__", escape(PRODUCT_FULL_NAME))
        .replace("__ENDORSEMENT__", escape(ENDORSEMENT))
        .replace("__PLAN__", plan_name)
        .replace("__PRO__", "true" if pro_enabled else "false")
        .replace("__INITIAL_PROJECT__", initial_project)
        .replace("__BRAND_ART__", escape(BRAND_ART_ROUTE, quote=True))
        .replace("__TAGLINE__", escape(TAGLINE))
    )


__all__ = ["router", "professional_editor_workspace"]
